-- Preguntas reales de Seguridad del paciente (tema 1) y Farmacia (tema 8, solo 2 preguntas).
-- Borra las respuestas y envíos de esos dos temas, porque las preguntas cambiaron.
DELETE FROM respuestas WHERE pregunta_id IN (SELECT id FROM preguntas WHERE tema_id IN (1, 8));
DELETE FROM envios_tema WHERE tema_id IN (1, 8);
UPDATE colaboradores SET enviado_en = NULL WHERE enviado_en IS NOT NULL;
DELETE FROM preguntas WHERE tema_id IN (1, 8);
INSERT INTO preguntas (tema_id, orden, enunciado, opciones, correcta) VALUES (1, 1, '¿Cuál es la principal importancia de los paquetes instruccionales de Seguridad del Paciente en las instituciones de salud?', '["Orientar al personal en la prevención de riesgos y el fortalecimiento de una atención segura", "Disminuir el tiempo destinado a la atención de los pacientes", "Aumentar la cantidad de procedimientos realizados diariamente", "Reemplazar los protocolos y las responsabilidades del personal asistencial"]', 0);
INSERT INTO preguntas (tema_id, orden, enunciado, opciones, correcta) VALUES (1, 2, '¿De qué manera contribuyen los paquetes instruccionales a prevenir eventos adversos durante la atención en salud?', '["Actuando solamente después de que se presenta un incidente", "Brindando herramientas para identificar, prevenir y reducir los riesgos asociados a la atención", "Concentrando la prevención de riesgos únicamente en el personal administrativo", "Promoviendo que cada profesional realice los procedimientos según su propio criterio"]', 1);
INSERT INTO preguntas (tema_id, orden, enunciado, opciones, correcta) VALUES (1, 3, '¿Por qué es fundamental que todo el personal de salud conozca y aplique los paquetes instruccionales?', '["Porque disminuyen la necesidad de comunicación entre los integrantes del equipo", "Porque facilitan cumplir únicamente con los requisitos documentales de la institución", "Porque fortalecen una cultura de seguridad y promueven prácticas que protegen al paciente", "Porque permiten delegar toda la responsabilidad de la seguridad al área de calidad"]', 2);
INSERT INTO preguntas (tema_id, orden, enunciado, opciones, correcta) VALUES (8, 1, 'Además de realizar el reporte en el aplicativo de Evento Adverso, ¿qué se debe hacer con una sospecha de reacción adversa?', '["Nada más, porque el reporte reemplaza el registro en la historia clínica", "Documentarla en la historia clínica: qué medicamento, qué signos y síntomas, cuándo empezaron y qué conducta se tomó", "Documentarla en la historia clínica solo si la reacción es grave", "Avisarle de palabra a la jefe de seguridad del paciente, sin dejar registro escrito"]', 1);
INSERT INTO preguntas (tema_id, orden, enunciado, opciones, correcta) VALUES (8, 2, 'Un paciente que recibe tramadol presenta estreñimiento leve, una reacción ya conocida de los opioides. ¿Qué se debe hacer?', '["No reportarlo, porque es una reacción esperada y ya descrita", "Reportarlo solo si se convierte en una reacción grave", "Reportarlo como sospecha de reacción adversa", "Esperar a confirmar que el tramadol fue la causa antes de reportar"]', 2);
